#include <cstdio>
#include <cstring>
#include <algorithm>
#include <vector>
#include <utility>

using namespace std;

#define SZ(v) ((int)(v).size())

const int maxint = -1u >> 1;

typedef long long ll;

int n, m;
vector<vector<short>> adj; // Using vector for dynamic memory management
vector<int> f, bestf;

int find(int v) {
    if (v != bestf[v]) {
        return bestf[v] = find(bestf[v]);
    }
    return v;
}

ll mincut() {
    ll ans = (-1ull) >> 1;
    for (int i = 0; i < n; ++i) {
        f[i] = i;
    }
    for (int t = n; t > 1; --t) {
        vector<bool> a(t, false);
        vector<ll> w(t, 0);
        a[0] = true;
        for (int i = 1; i < t; ++i) {
            a[i] = false;
            w[i] = adj[0][i];
        }
        int prev = 0;
        for (int i = 1; i < t; ++i) {
            int zj = -1;
            for (int j = 1; j < t; ++j) {
                if (!a[j] && (zj == -1 || w[j] > w[zj])) {
                    zj = j;
                }
            }
            a[zj] = true;
            if (i == t - 1) {
                if (w[zj] < ans) {
                    ans = w[zj];
                    copy(f.begin(), f.end(), bestf.begin());
                }
                for (int k = 0; k < t; ++k) {
                    adj[k][prev] += adj[zj][k];
                }
                f[zj] = prev;
                break;
            }
            prev = zj;
            for (int j = 1; j < t; ++j) {
                if (!a[j]) {
                    w[j] += adj[zj][j];
                }
            }
        }
    }
    return ans;
}

void gao() {
    ll ans = 0;
    adj.assign(n, vector<short>(n, 0)); // Resize adj using vector
    for (int i = 0; i < m; ++i) {
        int a, b;
        ll c;
        scanf("%d%d%lld", &a, &b, &c);
        if (c < 0) {
            ans += c;
        } else {
            adj[a][b] = adj[b][a] = adj[a][b] + c;
        }
    }
    printf("%lld\n", ans + mincut());
}

int main() {
    while (scanf("%d%d", &n, &m) == 2 && (n || m)) {
        f.resize(n);
        bestf.resize(n);
        gao();
    }
    return 0;
}

